var t=[{title:`Kies toegankelijke beweging`,text:`Wandelen, fietsen, zwemmen, ondersteunde squats en krachtoefeningen op machines kunnen comfortabele startplekken zijn, afhankelijk van je vermogen en voorkeur. Voor sommige mensen leggen joggen en herhaald springen meer druk op de gewrichten of ademhaling dan opties met lage impact. Lichaamsgrootte alleen maakt geen van deze activiteiten goed of fout.`},{title:`Begin met een dosis die je aankunt`,text:`Een korte wandeling of een paar sets ondersteunde krachtoefeningen kan genoeg zijn om de gewoonte op te bouwen. Voeg tijd, afstand of herhalingen geleidelijk toe naarmate je zelfvertrouwen en tolerantie groeien. Let op hoe beweging voelt en wat je volgende week kunt doen, en niet alleen op de weegschaal.`},{title:`Kijk naar meerdere resultaten`,text:`Makkelijker trappen oplopen, langere wandelingen, meer herhalingen en beter herstel tellen allemaal als vooruitgang. Veranderingen in lichaamsgewicht hangen af van veel factoren, waaronder eetpatronen, medicijnen en gezondheidsproblemen. Je fitheid kan verbeteren zonder grote verandering in gewicht.`},{title:`Begin waar je staat`,text:`Sommige mensen hebben al veel trainingservaring, terwijl anderen weinig uitrusting of privacy hebben. Pas oefeningen aan op je situatie. Afvallen hoeft niet je doel te zijn.`},{title:`TrainUp gebruiken`,text:`Stel in Profiel je trainingsruimte in, of springen mag, eventuele beperkingen per lichaamsdeel en je fitnessniveau. Het schema kiest alleen oefeningen die bij die instellingen passen. TrainUp leert oefenen en geeft geen dieetplannen of medische begeleiding bij gewichtsbeheersing, dus heb je klachten of complexe gezondheidsproblemen, vraag dan een arts om persoonlijk advies.`}];var i=[{label:`NHS: wandelen voor je gezondheid`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`},{label:`CDC: gezond gewicht en beweging`,url:`https://www.cdc.gov/healthy-weight-growth/losing-weight/`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};